package realestate.dao;
import realestate.model.*;import realestate.util.*;import java.sql.*;
public class UserDAO {
 public long register(String name,String email,String phone,String role,char[] password)throws SQLException{String sql="INSERT INTO users(name,email,password_hash,phone,role) VALUES(?,?,?,?,?)";try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(sql,Statement.RETURN_GENERATED_KEYS)){p.setString(1,name);p.setString(2,email.toLowerCase());p.setString(3,PasswordUtil.hash(password));p.setString(4,phone);p.setString(5,role);p.executeUpdate();try(ResultSet k=p.getGeneratedKeys()){k.next();return k.getLong(1);}}}
 public User login(String email,char[] password)throws SQLException{try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT user_id,name,email,phone,role,password_hash FROM users WHERE email=?")){p.setString(1,email.toLowerCase());try(ResultSet r=p.executeQuery()){if(!r.next()||!PasswordUtil.verify(password,r.getString("password_hash")))return null;long id=r.getLong("user_id");String n=r.getString("name"),e=r.getString("email"),ph=r.getString("phone");return switch(r.getString("role")){case "BUYER"->new Buyer(id,n,e,ph);case "SELLER"->new Seller(id,n,e,ph);case "ADMIN"->new Admin(id,n,e,ph);default->null;};}}}
 public void listUsers()throws SQLException{try(Connection c=DatabaseConnection.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT user_id,name,email,phone,role,created_at FROM users ORDER BY user_id")){while(r.next())System.out.printf("%d | %s | %s | %s | %s%n",r.getLong(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5));}}
}
